package com.randbox.randombox.network;
import com.randbox.randombox.loot.EditorData;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.resources.ResourceLocation;import net.minecraft.server.level.ServerPlayer;import net.minecraftforge.network.NetworkEvent;import java.util.function.Supplier;
public record SaveEntryPacket(String table,String item,int weight){public static void encode(SaveEntryPacket p,FriendlyByteBuf b){b.writeUtf(p.table,256);b.writeUtf(p.item,256);b.writeVarInt(p.weight);}public static SaveEntryPacket decode(FriendlyByteBuf b){return new SaveEntryPacket(b.readUtf(256),b.readUtf(256),b.readVarInt());}public static void handle(SaveEntryPacket p,Supplier<NetworkEvent.Context>s){ServerPlayer sp=s.get().getSender();s.get().enqueueWork(()->{ResourceLocation t=ResourceLocation.tryParse(p.table),i=ResourceLocation.tryParse(p.item);if(sp!=null&&sp.hasPermissions(2)&&t!=null&&i!=null&&net.minecraftforge.registries.ForgeRegistries.ITEMS.containsKey(i))EditorData.get(sp.serverLevel()).add(t,i,p.weight);});s.get().setPacketHandled(true);}}
